import csv
import sqlite3

def validate_employee_credentials(csv_file, db_path):
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    results = []
    with open(csv_file, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            username = row['username']
            password = row['password']

            # Query the database for this user
            query = f"SELECT id, name FROM employees WHERE username = '{username}' AND password = '{password}'"
            cursor.execute(query)

            user = cursor.fetchone()
            if user:
                results.append({
                    'username': username,
                    'status': 'valid',
                    'employee_id': user[0],
                    'name': user[1]
                })
            else:
                results.append({
                    'username': username,
                    'status': 'invalid'
                })

    conn.close()
    return results

if __name__ == '__main__':
    output = validate_employee_credentials('employees.csv', 'company.db')
    for result in output:
        print(result)
